"""Build a self-contained designer canvas from native captures; never invent captures."""
from pathlib import Path
import base64,json,html,hashlib,shutil,zipfile,math
from PIL import Image,ImageDraw,ImageFont
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'Reports/ScreenRoadmap-Oct09';OUT.mkdir(parents=True,exist_ok=True)
GROUPS=[
('01','Вход','Главное меню → карта. Настройки и кабинет — боковые ветки.', [('01-home','Главное меню'),('02-settings','Настройки: вход')]),
('02','История и карта','Комикс → карта → диалог. Личная миссия предлагает принять или отказаться.', [('29-comic','Комикс мира'),('08-map','Карта: дневной мир'),('09-map-night','Карта: ночной мир'),('30-dialogue','Диалог героя'),('mission-offer','Личная миссия: принять / отказаться')]),
('03','Выбор уровня','Активный остров → список уровней → выбранный уровень.', [('10-island','Уровни острова')]),
('04','Игра и управление','Урок первого этапа → три этапа. Сумка раскрывается прямо в игре.', [('33-tutorial','Обучение механике'),('20-game','Игра: фигуры'),('41-target','Просмотр цели'),('20a-inline-bag','Новая панель сумки'),('21-game-words','Игра: слова'),('22-game-mixed','Игра: микс'),('23-pause','Пауза')]),
('05','Результат и продолжение','Этап → следующий этап. Победа → следующий уровень / карта. Проигрыш → повтор.', [('24-checkpoint','Этап завершён'),('25-victory','Победа и статистика'),('26-failure','Проигрыш'),('27-parcel','Посылка'),('28-parcel-open','Открытая посылка'),('54-parcel-final','Посылка: финальное состояние'),('55-prize-final','Полученная награда'),('39-story-ending','Конец путешествия')]),
('06','Кабинет и коллекция','Кабинет открывается из главного меню. Рекорды, мастерская и вещи — его ветки.', [('34-journal','Мой кабинет / журнал'),('35-workshop','Мастерская'),('37-records','Мои пути / рекорды'),('38-contracts','Пути с печатями'),('17-bag','Мои вещи'),('18-trophies','Коллекция трофеев')]),
('07','Магазин','Тап выделяет предмет → отдельная кнопка открывает описание / предпросмотр.', [('11a-shop-shelf','Каталог инструментов'),('11-shop-tools','Выбранный инструмент'),('11b-tool-preview','Описание инструмента'),('12a-trophy-shelf','Каталог костюмов'),('12-shop-mika','Выбранный костюм'),('12b-costume-preview','Предпросмотр костюма'),('13-shop-background','Фон / живность'),('14-shop-frames','Рамки'),('15-coins','Пакеты монет'),('16-no-ads','Отключение рекламы')]),
('08','Настройки','Из меню: звук и движение, помощь, язык, напоминания, облачное сохранение.', [('03-settings-0','Звук и движение'),('04-settings-1','Удобство и помощь'),('05-settings-2','Язык интерфейса'),('06-settings-3','Напоминания'),('07-settings-4','Облачное сохранение'),('40-word-language','Язык игровых слов')]),
('09','Размеры и языки','Варианты для проверки дизайнером: узкий экран, крупный текст, EN / UK.', [('44-small-shop','Магазин: узкий экран'),('45-large-text','Меню: крупный текст'),('46-settings-large','Настройки: крупный текст UK'),('47-records-large','Рекорды: крупный текст UK'),('48-dialogue-large','Диалог: крупный текст UK'),('49-comic-large','Комикс: крупный текст UK'),('50-tool-large','Предмет: крупный текст UK'),('51-shop-english','Каталог: EN'),('52-coach-shelf','Подсказка каталога'),('53-coach-detail','Подсказка предпросмотра'),('56-guide-final','Помощь: вариант'),('57-guide-large','Помощь: крупный текст')]),
('10','Помощь и служебные состояния','Отдельная зона: не считать эти снимки обязательными шагами основного пути.', [('31-guide','Как играть'),('32-effect-guide','Объяснение эффектов'),('19-supplies','Старый каталог игровой сумки'),('36-requests','Прежний экран просьб — удалён из пути'),('42-test-ad','Тестовая реклама — только QA'),('43-save-recovery','Восстановление сохранения')])]
SOURCES=[OUT,ROOT/'Reports/NavigationType-Oct08',ROOT/'Reports/ClarityFinal-Oct08',ROOT/'Reports/AllScreens-Oct08']
entries=[];sections=[];imageout=OUT/'screens';imageout.mkdir(exist_ok=True)
for code,title,route,items in GROUPS:
 cards=[]
 for index,(stem,label) in enumerate(items,1):
  identity=f'{code}.{index:02d}';p=next((d/(stem+'.png') for d in SOURCES if (d/(stem+'.png')).is_file()),None)
  fresh=bool(p and p.parent==OUT);status='Свежий снимок' if fresh else 'Архив · 8 октября' if p else 'Нужен свежий снимок'
  rec={'id':identity,'file':stem+'.png','title':label,'group':title,'status':status,'source':str(p.relative_to(ROOT)) if p else None}
  if p:
   data=p.read_bytes();rec['sha256']=hashlib.sha256(data).hexdigest();shutil.copy2(p,imageout/(identity+'-'+p.name));url='data:image/png;base64,'+base64.b64encode(data).decode();im=Image.open(p);rec['width'],rec['height']=im.size
   visual=f'<img loading="lazy" src="{url}" alt="{html.escape(label)}" width="{im.width}" height="{im.height}">'
  else:visual='<div class="pending">Снимок пока недоступен<br><small>Unity не завершила обновление / запуск</small></div>'
  rec['url']=url if p else '';entries.append(rec)
  cards.append(f'<article class="card" id="s-{identity}" data-id="{identity}"><button class="shot" data-id="{identity}" aria-label="Открыть {html.escape(label)}">{visual}</button><div class="caption"><span class="number">{identity}</span><h3>{html.escape(label)}</h3><span class="badge {"fresh" if fresh else "archive" if p else "missing"}">{status}</span><button class="note" data-id="{identity}">Добавить правку</button></div></article>')
 sections.append(f'<section id="g{code}"><header class="group"><span>{code}</span><div><h2>{title}</h2><p>{route}</p></div></header><div class="cards">'+''.join(cards)+'</div></section>')
nav=''.join(f'<a href="#g{c}">{c} · {t}</a>' for c,t,_,_ in GROUPS)
metrics=[]
import csv,collections
p=ROOT/'Reports/CampaignRoadmap-Oct09/progression.csv'
if p.exists():
 rows=list(csv.DictReader(p.open()));
 for world in range(1,10):
  ss=[r for r in rows if int(r['world'])==world];metrics.append({'world':world,'mean':round(sum(int(s['minimum']) for s in ss)/len(ss),2),'mechanics':len(set(s['principle'] for s in ss))})
chart=''.join(f'<div class="barrow"><b>{m["world"]}</b><div style="width:{m["mean"]*24}px"></div><span>{m["mean"]} хода / этап · {m["mechanics"]} ведущих механик</span></div>' for m in metrics)
manifest=[{k:v for k,v in e.items() if k!='url'} for e in entries];(OUT/'manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2))
css='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;color:#19342f;background:#efeee6;font:15px system-ui,-apple-system,sans-serif}a{color:inherit}header.top{padding:32px 36px;background:#123a36;color:#f5efd9}h1{margin:0 0 10px;font-size:30px;letter-spacing:-.6px}.top p{margin:0;max-width:1000px;color:#d8e1d8;line-height:1.5}.warning{background:#ffedc5;padding:14px 36px;line-height:1.5;border-bottom:1px solid #d7bd81}.controls{display:flex;gap:10px;align-items:center;padding:12px 24px;background:#fcfbf5;position:sticky;top:0;z-index:5;border-bottom:1px solid #ccd1c3}button{font:inherit;cursor:pointer;border:1px solid #b8c6ba;border-radius:8px;background:#fffef8;color:#19342f;padding:8px 12px}.controls .right{margin-left:auto;font-size:13px}nav{display:flex;flex-wrap:wrap;gap:9px;padding:18px 36px}nav a{text-decoration:none;border:1px solid #c7d0c1;border-radius:18px;padding:7px 12px;background:#f8f8f1;font-size:13px}.mainpath{margin:4px 36px 24px;background:#fffef8;border:1px solid #c8d1bf;border-radius:12px;padding:18px;line-height:1.9}main{padding:0 36px 45px;transform-origin:0 0}section{margin-bottom:40px;scroll-margin-top:70px}.group{display:flex;gap:14px;align-items:center;margin:0 0 16px}.group>span{color:#b6ad74;background:#193f37;padding:14px 16px;border-radius:10px;font-size:26px;font-weight:700}h2{font-size:24px;margin:0 0 5px}.group p{margin:0;color:#5c6e60;font-size:14px}.cards{display:flex;flex-wrap:wrap;gap:16px}.card{width:216px;background:#fcfbf5;border:1px solid #c5cbbc;border-radius:12px;overflow:hidden;box-shadow:0 3px 9px #173d3112}.shot{padding:0;border:0;border-radius:0;display:block;width:100%;background:#dcded0;aspect-ratio:390/844;overflow:hidden}.shot img{width:100%;height:100%;display:block;object-fit:contain}.pending{display:flex;align-items:center;justify-content:center;flex-direction:column;gap:15px;height:100%;padding:25px;font-weight:650;color:#7e6746;font-size:17px;border:2px dashed #bfab83;background:#f5f0df}.pending small{font-weight:400;font-size:13px}.caption{padding:13px}.number{font-size:12px;font-weight:700;color:#738052}h3{font-size:15px;line-height:1.35;margin:5px 0 10px;min-height:40px}.badge{font-size:11px;display:inline-block;padding:4px 7px;border-radius:5px}.archive{color:#735516;background:#eee4c5}.missing{background:#ead7ce;color:#85472e}.fresh{background:#d9eee2;color:#236445}.note{display:block;padding:5px 0;margin-top:9px;font-size:12px;border:0;background:none;text-decoration:underline}.card.hasnote{border:2px solid #a66c31}.audit{margin:0 36px 32px;padding:20px;background:#fffef8;border:1px solid #c8d1bf;border-radius:12px}.audit summary{font-weight:650;cursor:pointer}.audit p{max-width:1050px;line-height:1.5}.barrow{display:flex;gap:12px;align-items:center;font-size:13px;margin:9px 0}.barrow b{width:15px}.barrow div{height:13px;border-radius:3px;background:#397465}.barrow span{color:#596b5d}dialog{width:min(1000px,95vw);border:0;border-radius:14px;background:#f9f7ee;padding:16px;color:#183c33}dialog::backdrop{background:#082820d9}.modalgrid{display:grid;grid-template-columns:minmax(240px,380px) 1fr;gap:22px}dialog img{width:100%;max-height:80vh;object-fit:contain}textarea{width:100%;min-height:220px;margin:14px 0;background:#fffefb;border:1px solid #bbc7b7;border-radius:8px;padding:12px;font:inherit;line-height:1.5}.meta{font-size:12px;color:#667457;word-break:break-word}.close{float:right}.foot{padding:18px 36px;color:#60705e;font-size:12px}@media(max-width:650px){header.top,.warning,main,nav{padding-left:16px;padding-right:16px}.card{width:calc(50% - 8px)}.modalgrid{grid-template-columns:1fr}dialog img{max-height:50vh}.right{display:none}}'''
js='''const entries=ENTRIES.map(e=>({...e,url:document.getElementById('s-'+e.id)?.querySelector('img')?.src||''}));const store='cascade-roadmap-oct09-notes';let notes={};try{notes=JSON.parse(localStorage.getItem(store)||'{}')}catch{}let active;const dlg=document.querySelector('dialog');function mark(){document.querySelectorAll('.card').forEach(c=>c.classList.toggle('hasnote',!!notes[c.dataset.id]))}function show(id){active=entries.find(e=>e.id===id);document.querySelector('#modalTitle').textContent=active.id+' · '+active.title;const im=document.querySelector('#full');im.src=active.url;im.style.display=active.url?'block':'none';document.querySelector('#meta').textContent=active.status+' · '+(active.source||'Снимок ожидается');document.querySelector('textarea').value=notes[id]||'';if(!dlg.open)dlg.showModal()}document.querySelectorAll('.shot,.note').forEach(b=>b.onclick=()=>show(b.dataset.id));document.querySelector('#close').onclick=()=>dlg.close();document.querySelector('#saveNote').onclick=()=>{notes[active.id]=document.querySelector('textarea').value.trim();localStorage.setItem(store,JSON.stringify(notes));mark();dlg.close()};let zoom=1;function scale(v){zoom=Math.min(1.5,Math.max(.35,v));document.querySelector('main').style.zoom=zoom;document.querySelector('#zoom').textContent=Math.round(zoom*100)+'%'}document.querySelector('#plus').onclick=()=>scale(zoom+.1);document.querySelector('#minus').onclick=()=>scale(zoom-.1);document.querySelector('#reset').onclick=()=>scale(1);document.querySelector('#export').onclick=()=>{const data={created:new Date().toISOString(),canvas:'ScreenRoadmap-Oct09',comments:entries.filter(e=>notes[e.id]).map(e=>({id:e.id,title:e.title,file:e.file,captureStatus:e.status,comment:notes[e.id]}))};const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download='cascade-designer-notes.json';a.click();URL.revokeObjectURL(a.href)};mark();'''.replace('ENTRIES',json.dumps(manifest,ensure_ascii=False).replace('</','<\\/'))
page=f'''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CASCADE · карта экранов для дизайнера</title><style>{css}</style><header class="top" id="top"><h1>CASCADE · путь игрока и карта экранов</h1><p>Номера вида 04.03 — адреса для правок. Нажми экран, чтобы увеличить и добавить комментарий. Правки сохраняются в этом браузере; «Экспорт правок» выгружает файл для передачи.</p></header><div class="warning"><strong>Статус снимков:</strong> свежая съёмка пока заблокирована обновлением редактора и службой лицензии при закрытом Mac. Использованы последние доступные настоящие снимки от 8 октября. Они не подтверждают внешний вид правок 9 октября. Новая сумка и новые окна отмечены как ожидающие съёмки.</div><div class="controls"><a href="#top">К маршруту</a><button id="minus">−</button><span id="zoom">100%</span><button id="plus">+</button><button id="reset">Сброс</button><button id="export">Экспорт правок</button><span class="right">{sum(bool(e['source']) for e in entries)} снимков · {sum(not e['source'] for e in entries)} ожидаются</span></div><nav>{nav}</nav><div class="mainpath"><strong>Основной маршрут</strong><br>01 Главное меню → 02 История и карта → 03 Остров и уровень → 04 Урок / игра → 05 Следующий этап → победа → следующий уровень или карта<br><strong>Боковые ветки:</strong> карта ↔ личная миссия · меню ↔ кабинет ↔ коллекция · меню / карта ↔ магазин · меню ↔ настройки.</div><details class="audit"><summary>Проверка пути и сложности кампании · 9 октября</summary><p>Изменены 62 набора. Проверены фактически опубликованные 540 трёхэтапных уровней: 1620 оптимальных сертификатов, 6471 primary / localized прохождение, 335 сроков бомб, 646 проверок необходимости полезных эффектов и 3292 пробы уменьшенной прочности. Нет точных повторов наборов, лишних стартовых преобразований и неиспользуемых платформ. Среднее число оптимальных действий — лишь один показатель; удовольствие и ощущение сложности требуют игрового просмотра. Свежие проверки касаний, перехода 6 → 7 и панели в Unity пока заблокированы.</p><p>Мир → среднее оптимальных действий на этап:</p>{chart}</details><main>{''.join(sections)}</main><div class="foot">Снимки — Unity Editor, не iPhone. Тестовый профиль. Для правок используйте номер экрана; архивные снимки перед финальным согласованием нужно переснять.</div><dialog><button class="close" id="close">Закрыть</button><h2 id="modalTitle"></h2><div class="modalgrid"><img id="full" alt="Увеличенный экран"><div><p class="meta" id="meta"></p><label for="notes">Правка дизайнера</label><textarea id="notes" placeholder="Что изменить, где и какой результат нужен"></textarea><button id="saveNote">Сохранить правку</button><p class="meta">Для отправки всех комментариев нажмите «Экспорт правок» на холсте.</p></div></div></dialog><script>{js}</script></html>'''
(OUT/'roadmap.html').write_text(page)
# Standalone overview built only from the same native captures.
font='/System/Library/Fonts/Supplemental/Arial.ttf';F=lambda n:ImageFont.truetype(font,n)
W=2032;cw=224;gap=20;left=40;per=8;heights=[110+math.ceil(len(items)/per)*580 for _,_,_,items in GROUPS];H=230+sum(heights);canvas=Image.new('RGB',(W,H),'#efeee6');d=ImageDraw.Draw(canvas)
d.rectangle((0,0,W,190),fill='#123a36');d.text((40,28),'CASCADE / Карта экранов по шагам',font=F(42),fill='#f7efd9');d.text((40,95),'Архивные снимки 8 октября. Изменения 9 октября требуют свежей съёмки.',font=F(24),fill='#e2dac4');d.text((40,138),'Подробный холст и комментарии: roadmap.html',font=F(23),fill='#d4e3d7');y=220;at=0
for code,title,route,items in GROUPS:
 d.text((40,y),code+' / '+title,font=F(33),fill='#193f37');d.text((40,y+43),route,font=F(22),fill='#61705e');y+=90
 for j,_ in enumerate(items):
  e=entries[at];at+=1;x=left+(j%per)*(cw+gap);cy=y+(j//per)*580
  d.rounded_rectangle((x,cy,x+cw,cy+552),10,fill='#fffdf5',outline='#bac5b4')
  if e['source']:
   im=Image.open(ROOT/e['source']).convert('RGB');im.thumbnail((cw-10,470));canvas.paste(im,(x+(cw-im.width)//2,cy+5))
  else:d.text((x+16,cy+180),'Ожидается\nсвежий снимок',font=F(22),fill='#856849')
  d.text((x+10,cy+478),e['id']+' / '+('АРХИВ' if e['source'] else 'ОЖИДАЕТСЯ'),font=F(16),fill='#8b6c25')
  label=e['title'];words=label.split();lines=[];line=''
  for word in words:
   trial=(line+' '+word).strip()
   if d.textlength(trial,font=F(19))>cw-20 and line:lines.append(line);line=word
   else:line=trial
  lines.append(line);d.text((x+10,cy+504),'\n'.join(lines[:2]),font=F(19),fill='#213c32')
 y+=math.ceil(len(items)/per)*580+20
canvas.save(OUT/'roadmap-overview.png',optimize=True)
with zipfile.ZipFile(OUT/'designer-pack.zip','w',zipfile.ZIP_DEFLATED) as z:
 for p in [OUT/'roadmap.html',OUT/'roadmap-overview.png',OUT/'manifest.json',*imageout.glob('*.png')]:z.write(p,p.relative_to(OUT))
print(f'Canvas: {len(entries)} states; {sum(bool(e["source"]) for e in entries)} native archived captures; {sum(not e["source"] for e in entries)} pending. {W}x{H} overview.')
